consolidated.slot.tsx
import { useCallback, useEffect, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useSheetDueTotal, useSheetOverdue } from '../header/totals';
import { usePeople } from '../people/people';
import { sum } from '../rates/rates';

/** The ids of the sheet's descendants: the sheets naming it as their parent, then theirs, and so on. */
function useDescendants(sheetId: string) {
  return useQuery({
    queryKey: ['sheet', sheetId, 'descendants'],
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/descendants`),
  });
}

/** One sheet's own figures, as its header shows them. */
type Figures = { people: number; due: string; overdue: string };

/** Works out one sheet's figures with the same hooks as its header, and reports them. Shows nothing. */
function SheetFigures({ sheetId, report }: { sheetId: string; report: (sheetId: string, f: Figures) => void }) {
  const people = (usePeople(sheetId).data ?? []).length;
  const due = useSheetDueTotal(sheetId);
  const overdue = useSheetOverdue(sheetId).total;
  useEffect(() => report(sheetId, { people, due, overdue }), [report, sheetId, people, due, overdue]);
  return null;
}

/** The consolidated figures over the sheet and all its descendants: their people counted, and each sheet's
 *  due-total and overdue-total (as that sheet shows it) added up. A sheet with no children shows its own. While an
 *  as-of date is set (see features/asof), every sheet of the tree is read as it stood at the end of that date, with
 *  that date as its today. */
function Consolidated({ sheetId }: { sheetId: string }) {
  const descendants = useDescendants(sheetId);
  const sheets = [sheetId, ...(descendants.data ?? [])];
  const [figures, setFigures] = useState<Record<string, Figures>>({});
  const report = useCallback(
    (id: string, f: Figures) => setFigures((all) => ({ ...all, [id]: f })),
    [],
  );
  const counted = sheets.map((id) => figures[id]).filter((f): f is Figures => f !== undefined);

  return (
    <section data-testid="consolidated">
      {sheets.map((id) => (
        <SheetFigures key={id} sheetId={id} report={report} />
      ))}
      Consolidated: people <span data-testid="consolidated-people-count">{counted.reduce((n, f) => n + f.people, 0)}</span>
      {' · '}Due total <span data-testid="consolidated-due-total">{sum(counted.map((f) => f.due))}</span>
      {' · '}Overdue total <span data-testid="consolidated-overdue-total">{sum(counted.map((f) => f.overdue))}</span>
    </section>
  );
}

export const contribution = SheetPage.fill({ order: -9, Component: Consolidated });
import { SheetPage } from '../../slots/defs/sheetPage';
import { isActive } from '../active/active';
import { live, useClaims } from '../claims/claims';
import { STATUSES, useStatusCounts } from '../header/totals';
import { GRADES, gradeOn, usePeople } from '../people/people';
import { periodDue, usePeriods } from '../periods/periods';
import { difference, personDue, sum, useRates } from '../rates/rates';
import { isReviewLate } from '../overdue/late';
import { useCap, useFloor, useLate, useReviewSla } from '../settings/settings';
import { useVoidReasons } from '../voidreasons/voidreasons';

/** The sheet's summary, worked out from the same figures the lists show. Per grade: the people on it on the sheet's
 *  today (retired people excluded), their due-totals added up (skipping n/a) and how many of them are active. Per period: its due-total, and its
 *  change from the period before it by start date (blank for the earliest). Per
 *  status: how many of the sheet's claims have it, and how many REVIEW claims are review-late (see isReviewLate). Per void reason on the sheet's list: how many VOID claims were voided
 *  with it. */
function Summary({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const periods = usePeriods(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const cap = useCap(sheetId);
  const reviewSla = useReviewSla(sheetId);

  const active = (people.data ?? []).filter((p) => p.retiredFrom === null);
  const onGrade = (grade: string) => active.filter((p) => gradeOn(p, late.today) === grade);
  const gradeDue = (grade: string) =>
    sum(
      onGrade(grade).map((p) =>
        personDue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p], late.today), rates.data, p, late, floor, cap),
      ),
    );
  const byStart = [...(periods.data ?? [])].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
  const dueOf = new Map(byStart.map((p) => [p.id, periodDue(p, claims.data, people.data, rates.data, floor, late)]));
  const changeOf = new Map(
    byStart.map((p, i) => [p.id, i === 0 ? '' : difference(dueOf.get(p.id)!, dueOf.get(byStart[i - 1].id)!)]),
  );
  const withStatus = useStatusCounts(sheetId);
  const voidReasons = useVoidReasons(sheetId);

  return (
